package config

import (
	"fmt"
	"testing"
)

var mergeStateSink *AppState

func BenchmarkMergeAppStateAccess(b *testing.B) {
	for _, history := range []int{0, 1000} {
		for _, operation := range []string{"read", "unchanged", "update"} {
			b.Run(fmt.Sprintf("history=%d/%s", history, operation), func(b *testing.B) {
				b.Setenv("CONFIG_DIR", b.TempDir())
				b.Setenv("LG_CONFIG_FILE", "")
				c, err := NewAppConfig("lazygit", "unversioned", "", "", "", false, b.TempDir())
				if err != nil {
					b.Fatal(err)
				}
				if err := mergeUpdateAppState(c, func(state *AppState) {
					for i := range history {
						state.ShellCommandsHistory = append(state.ShellCommandsHistory, fmt.Sprintf("git show commit-%04d", i))
					}
				}); err != nil {
					b.Fatal(err)
				}
				var run func() error
				switch operation {
				case "read":
					run = func() error {
						var err error
						mergeStateSink, err = mergeReadAppState(c)
						return err
					}
				case "unchanged":
					run = func() error { return mergeUpdateAppState(c, func(*AppState) {}) }
				case "update":
					run = func() error {
						return mergeUpdateAppState(c, func(state *AppState) { state.LastUpdateCheck++ })
					}
				}
				b.ReportAllocs()
				b.ResetTimer()
				for b.Loop() {
					if err := run(); err != nil {
						b.Fatal(err)
					}
				}
			})
		}
	}
}

func BenchmarkMergeAppStateReadParallel(b *testing.B) {
	b.Setenv("CONFIG_DIR", b.TempDir())
	b.Setenv("LG_CONFIG_FILE", "")
	c, err := NewAppConfig("lazygit", "unversioned", "", "", "", false, b.TempDir())
	if err != nil {
		b.Fatal(err)
	}
	if err := mergeUpdateAppState(c, func(state *AppState) {
		for i := range 1000 {
			state.ShellCommandsHistory = append(state.ShellCommandsHistory, fmt.Sprintf("git show commit-%04d", i))
		}
	}); err != nil {
		b.Fatal(err)
	}
	b.SetParallelism(8)
	b.ReportAllocs()
	b.ResetTimer()
	b.RunParallel(func(pb *testing.PB) {
		for pb.Next() {
			state, err := mergeReadAppState(c)
			if err != nil || len(state.ShellCommandsHistory) != 1000 {
				b.Error("could not read history")
			}
		}
	})
}

func mergeReadAppState(c *AppConfig) (*AppState, error) { return c.GetAppState(), nil }
func mergeUpdateAppState(c *AppConfig, update func(*AppState)) error { update(c.GetAppState()); return c.SaveAppState() }

